    }

    // Elevator ladder.
    for (const z of [-0.96, -0.68]) {
      addBox(elevator, [0.06, 11.8, 0.06], [-0.91, 6, z], material.steel);
    }

    for (let y = 0.3; y < 11.8; y += 0.42) {
      addBox(
        elevator,
