    );
    hopperBody.rotation.y = Math.PI / 4;

    // Hopper rim.
    addBox(hopper, [2.1, 0.12, 0.13], [0, 11.06, 0.85], material.yellow);
    addBox(hopper, [2.1, 0.12, 0.13], [0, 11.06, -0.85], material.yellow);
    addBox(hopper, [0.13, 0.12, 1.7], [0.85, 11.06, 0], material.yellow);
    addBox(hopper, [0.13, 0.12, 1.7], [-0.85, 11.06, 0], material.yellow);

    // Regolith visible in the hopper.
    for (let i = 0; i < 12; i++) {
      const rock = new THREE.Mesh(
        new THREE.IcosahedronGeometry(0.13 + (i % 3) * 0.035, 0),
        material.rock
      );
      rock.position.set(
        (Math.random() - 0.5) * 1.45,
        10.78 + Math.random() * 0.12,
        (Math.random() - 0.5) * 1.45
      );
      rock.scale.y = 0.6 + Math.random() * 0.5;
      rock.rotation.set(Math.random(), Math.random(), Math.random());
      hopper.add(rock);
