    // Discharge stem and press assembly.
    addCylinder(
      hopper,
      0.27,
      0.27,
      4.35,
      [0, 6.65, 0],
      material.steel,
      20
    );

    addCylinder(
      hopper,
      0.36,
      0.36,
      0.32,
