    // Trolley carriage.
    addBox(pressAssembly, [1.75, 0.55, 1.7], [0, 8.2, 0], material.dark);
    addBox(pressAssembly, [1.25, 0.3, 1.2], [0, 8.55, 0], material.yellow);

    for (const x of [-0.55, 0.55]) {
      for (const z of [-0.58, 0.58]) {
        const wheel = addCylinder(
          pressAssembly,
          0.22,
          0.22,
