    // -------------------------------------------------------------------------
    // Direct camera controls: orbit, pan, zoom, and touch support
    // -------------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(0, 4, 0),
      radius: 44,
      theta: 0.72,
      phi: 1.08
    };

    const cameraGoal = {
      target: cameraState.target.clone(),
      radius: cameraState.radius,
      theta: cameraState.theta,
      phi: cameraState.phi
    };

    function setCameraView(view) {
      const views = {
        overview: {
          target: new THREE.Vector3(0, 4, 0),
          radius: 44,
          theta: 0.72,
          phi: 1.08
        },
        gantry: {
          target: new THREE.Vector3(0, 5, 0),
          radius: 20,
          theta: 0.15,
          phi: 1.18
        },
        kiln: {
          target: new THREE.Vector3(0, 2, 0),
          radius: 30,
          theta: 1.15,
          phi: 1.25
        }
      };

      const selected = views[view];
      cameraGoal.target.copy(selected.target);
      cameraGoal.radius = selected.radius;
      cameraGoal.theta = selected.theta;
      cameraGoal.phi = selected.phi;

      document.querySelectorAll("[data-view]").forEach((button) => {
        button.classList.toggle("active", button.dataset.view === view);
      });
    }

    const canvas = renderer.domElement;
    const pointer = {
      active: false,
      x: 0,
      y: 0,
      button: 0
    };

    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    canvas.addEventListener("pointerdown", (event) => {
      pointer.active = true;
      pointer.x = event.clientX;
      pointer.y = event.clientY;
      pointer.button = event.button;
      canvas.setPointerCapture(event.pointerId);
      canvas.classList.add("dragging");
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointer.active) return;

      const dx = event.clientX - pointer.x;
      const dy = event.clientY - pointer.y;
      pointer.x = event.clientX;
      pointer.y = event.clientY;

      if (event.shiftKey || pointer.button === 2) {
        const scale = cameraGoal.radius * 0.0015;
        const right = new THREE.Vector3(
          Math.cos(cameraGoal.theta),
          0,
          -Math.sin(cameraGoal.theta)
        );

        cameraGoal.target.addScaledVector(right, -dx * scale);
        cameraGoal.target.y += dy * scale;
        cameraGoal.target.x = THREE.MathUtils.clamp(
          cameraGoal.target.x,
          -25,
          25
        );
        cameraGoal.target.y = THREE.MathUtils.clamp(
          cameraGoal.target.y,
          0,
          15
        );
        cameraGoal.target.z = THREE.MathUtils.clamp(
          cameraGoal.target.z,
          -12,
          12
        );
      } else {
        cameraGoal.theta -= dx * 0.006;
        cameraGoal.phi = THREE.MathUtils.clamp(
          cameraGoal.phi - dy * 0.005,
          0.25,
          1.46
        );
      }

      cameraState.target.copy(cameraGoal.target);
      cameraState.radius = cameraGoal.radius;
      cameraState.theta = cameraGoal.theta;
      cameraState.phi = cameraGoal.phi;
    });

    function endPointer(event) {
      pointer.active = false;
