          75
        );
        cameraState.radius = cameraGoal.radius;
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", () => setCameraView("overview"));

    // -------------------------------------------------------------------------
    // Process animation
    // -------------------------------------------------------------------------

    const stageElement = document.getElementById("stage");
    const temperatureElement = document.getElementById("temperature");
    const carsElement = document.getElementById("cars-sintered");
    const progressElement = document.getElementById("progress-fill");
    const cycleElement = document.getElementById("cycle-time");
    const pauseButton = document.getElementById("pause");

    let simulationTime = 0;
    let running = true;
    const cycleDuration = 18;

    pauseButton.addEventListener("click", () => {
      running = !running;
      pauseButton.textContent = running ? "Pause" : "Resume";
      pauseButton.classList.toggle("active", !running);
    });

    document.querySelectorAll("[data-view]").forEach((button) => {
      button.addEventListener("click", () => {
        setCameraView(button.dataset.view);
      });
    });

    function smooth01(value) {
      const t = THREE.MathUtils.clamp(value, 0, 1);
      return t * t * (3 - 2 * t);
    }

    function updateProcess(time) {
      const phase = time % cycleDuration;
      let carX = -12;
      let pressDrop = 0;

      // Position, press, lift, transfer, and return sequence.
      if (phase >= 2 && phase < 3.5) {
        pressDrop = smooth01((phase - 2) / 1.5);
      } else if (phase >= 3.5 && phase < 4.5) {
        pressDrop = 1;
      } else if (phase >= 4.5 && phase < 6) {
        pressDrop = 1 - smooth01((phase - 4.5) / 1.5);
        carX = THREE.MathUtils.lerp(-12, 0, smooth01((phase - 4.5) / 1.5));
      } else if (phase >= 6 && phase < 8.5) {
        carX = 0;
      } else if (phase >= 8.5 && phase < 10) {
        pressDrop = 1 - smooth01((phase - 8.5) / 1.5);
        carX = THREE.MathUtils.lerp(0, 12, smooth01((phase - 8.5) / 1.5));
      } else if (phase >= 10 && phase < 11.5) {
        pressDrop = smooth01((phase - 10) / 1.5);
        carX = 12;
      } else if (phase >= 11.5 && phase < 12.5) {
        pressDrop = 1;
        carX = 12;
      } else if (phase >= 12.5 && phase < 14.5) {
        pressDrop = 1 - smooth01((phase - 12.5) / 2);
        carX = THREE.MathUtils.lerp(12, -12, smooth01((phase - 12.5) / 2));
      } else {
        carX = -12;
      }

      pressAssembly.position.x = carX;
      pressHead.position.y = -pressDrop;

      let stage;
      if (phase < 2) {
        stage = "POSITIONING OVER CAR 01";
      } else if (phase < 3.5) {
        stage = "HYDRAULIC PRESSURE";
      } else if (phase < 4.5) {
        stage = "HEAT DISTRIBUTION";
      } else if (phase < 6) {
        stage = "TRANSFERRING TO CAR 02";
      } else if (phase < 7.5) {
        stage = "PRESSING CAR 02";
      } else if (phase < 8.5) {
        stage = "HEAT DISTRIBUTION";
      } else if (phase < 10) {
        stage = "TRANSFERRING TO CAR 03";
      } else if (phase < 11.5) {
        stage = "PRESSING CAR 03";
      } else if (phase < 12.5) {
        stage = "HEAT DISTRIBUTION";
      } else if (phase < 14.5) {
        stage = "RETURNING TO START";
      } else {
        stage = "CYCLE COMPLETE / RESET";
      }

      stageElement.textContent = stage;

      const temperature = 580 + pressDrop * 150;
      temperatureElement.textContent = `${Math.round(temperature)} °C`;

      let carsSintered = 0;
      if (phase >= 14.5) carsSintered = 3;
      else if (phase >= 12.5) carsSintered = 2;
      else if (phase >= 11.5) carsSintered = 2;
      else if (phase >= 10) carsSintered = 1;
      else if (phase >= 7.5) carsSintered = 1;
      else if (phase >= 5) carsSintered = 0;

      carsElement.textContent = `${carsSintered} / 3`;
      progressElement.style.width = `${(phase / cycleDuration) * 100}%`;
      cycleElement.textContent = `${phase.toFixed(1).padStart(4, "0")} s`;

      // Animate the bucket elevator.
      for (let i = 0; i < elevatorBuckets.length; i++) {
        const bucket = elevatorBuckets[i];
        const travel = 0.7 + ((i * 1.18 + simulationTime * 1.12) % 11.2);
        bucket.position.y = travel;
        bucket.rotation.z = Math.sin(simulationTime * 2.2 + i) * 0.035;
      }

      // Falling material appears only while the press is active.
      const activePress =
        phase >= 3.3 && phase < 12.7 && pressDrop > 0.05;

      for (const particle of fallingParticles) {
        particle.mesh.visible = activePress;

        if (activePress) {
          const progress = (simulationTime * particle.speed + particle.phase) % 1;
          const targetY = 4.4 - pressDrop;
          const startY = 9.05;

          particle.mesh.position.y = THREE.MathUtils.lerp(
            startY,
            targetY,
            progress
          );

          particle.mesh.position.x =
            carX + particle.offsetX * (1 - progress * 0.7);

          particle.mesh.position.z =
            particle.offsetZ * (1 - progress * 0.55);

          const scale = 0.55 + progress * 2.2;
          particle.mesh.scale.setScalar(scale);
        }
      }

      kilnLights.forEach((light, index) => {
        light.intensity =
          31 + Math.sin(simulationTime * 3.2 + index * 1.7) * 4;
      });

      hopperBody.material.emissive.setHex(0x000000);
      hopperBody.material.emissiveIntensity =
        activePress ? 0.8 + Math.sin(simulationTime * 5) * 0.35 : 0;
    }

    // -------------------------------------------------------------------------
    // Resize and render loop
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const dt = Math.min(clock.getDelta(), 0.05);

      if (running) {
        simulationTime += dt;
      }

      updateProcess(simulationTime);

      // Smooth camera preset transitions.
      const cameraBlend = 1 - Math.exp(-dt * 8);
      cameraState.target.lerp(cameraGoal.target, cameraBlend);
      cameraState.radius = THREE.MathUtils.lerp(
        cameraState.radius,
        cameraGoal.radius,
        cameraBlend
      );
      cameraState.theta = THREE.MathUtils.lerp(
        cameraState.theta,
        cameraGoal.theta,
        cameraBlend
      );
      cameraState.phi = THREE.MathUtils.lerp(
        cameraState.phi,
        cameraGoal.phi,
        cameraBlend
      );

      const sinPhi = Math.sin(cameraState.phi);
      camera.position.set(
        cameraState.target.x +
          cameraState.radius * sinPhi * Math.sin(cameraState.theta),
        cameraState.target.y + cameraState.radius * Math.cos(cameraState.phi),
        cameraState.target.z +
          cameraState.radius * sinPhi * Math.cos(cameraState.theta)
      );

      camera.lookAt(cameraState.target);

      renderer.render(scene, camera);
    }

    updateProcess(0);
    animate();

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hidden");
    });
  </script>
